@pytest.mark.parametrize('actual', ['execution_job_submission', 'structural_homology_evidence/execution_job_submission', 'hpc_work_planning/execution_job_submission', 'hpc_work_planning/hpc_allocation_execution/execution_job_submission', 'structural_homology_evidence/hpc_work_planning/execution_job_submission', 'structural_homology_evidence/hpc_work_planning/hpc_allocation_execution/execution_job_submission'], indirect=['actual'], ids=['home=execution_job_submission', 'home=structural_homology_evidence/execution_job_submission', 'home=hpc_work_planning/execution_job_submission', 'home=hpc_work_planning/hpc_allocation_execution/execution_job_submission', 'home=structural_homology_evidence/hpc_work_planning/execution_job_submission', 'home=structural_homology_evidence/hpc_work_planning/hpc_allocation_execution/execution_job_submission'])
def test_actual_constructor_exact_private_identity_and_original_configuration(actual):
    observed = configuration_observations(actual)
    expected = ['tool', 'child', 'redeliver_report'] if 'hpc_work_planning' in actual.home.split('/') else ['tool', 'reason', 'child', 'wait', 'redeliver_report']
    assert observed['actions'] == expected
    assert observed['yield_binding'] == {'status': 'returned', 'value': {'class': 'BoundedYieldController'}}
    assert observed['unsupported_foreign_role']['status'] == 'raised'
    assert observed['unsupported_foreign_role']['message'] == 'unknown_execution_episode_role'
    assert actual.binding.as_record()['configuration'] == actual.configuration

