def test_original_build_selects_concrete_private_task_when_connected(actual, monkeypatch):
    v = actual
    runtime = v.runtime
    registry = own('episode_bindings').EpisodeBindingRegistry((v.binding,))
    monkeypatch.setattr(runtime.Episode, 'identity', lambda *args, **kwargs: SimpleNamespace(episode_id=v.context.episode_id))
    monkeypatch.setattr(runtime, 'FeedbackEpisode', lambda grain, key, source, *args, **kwargs: source)
    initialized = []
    monkeypatch.setattr(v.binding, 'initialize', lambda context: initialized.append(context))
    workflow = SimpleNamespace(context=object(), grains={'launch': object()}, inprocess_completion_order=None, receipts=None, structural_homology_evidence_binding=None, episode_bindings=registry, contract_information_profile=lambda source: None, specialist=lambda source: v.binding, binding_context=lambda source: v.context, journal=SimpleNamespace(row=lambda *args: None, save=lambda *args: None), run_id=v.journal.run_id, store=SimpleNamespace(transaction=nullcontext, db=SimpleNamespace(execute=lambda *args: None)), source_credit_view=lambda source: {'credit': 0.0}, expose_assigned_job=lambda source: None, receive_tool_attributions=lambda *args, **kwargs: None, archive=SimpleNamespace(store=lambda value: value), launch_instructions=SimpleNamespace(materialize=lambda value: None))
    task = runtime.Workflow.build(workflow, 'launch', 'original-work', 'Select an original resource handoff', runtime._plain(v.context.scope), episode_assignment=deepcopy(v.assignment))
    assert type(task) is getattr(v.binding, 'decision_source_type', runtime.DecisionSource)
    assert task.path == (('launch', 'original-work'),) and initialized == [v.context]
    if hasattr(v.binding, 'decision_source_type'):
        assert not isinstance(task, runtime.DecisionSource)

@pytest.mark.parametrize('actual', ['execution_job_submission', 'structural_homology_evidence/execution_job_submission', 'hpc_work_planning/execution_job_submission', 'hpc_work_planning/hpc_allocation_execution/execution_job_submission', 'structural_homology_evidence/hpc_work_planning/execution_job_submission', 'structural_homology_evidence/hpc_work_planning/hpc_allocation_execution/execution_job_submission'], indirect=['actual'], ids=['home=execution_job_submission', 'home=structural_homology_evidence/execution_job_submission', 'home=hpc_work_planning/execution_job_submission', 'home=hpc_work_planning/hpc_allocation_execution/execution_job_submission', 'home=structural_homology_evidence/hpc_work_planning/execution_job_submission', 'home=structural_homology_evidence/hpc_work_planning/hpc_allocation_execution/execution_job_submission'])
def test_instruction_text_retains_original_launch_goal_and_ancestry_rules(actual):
    task = make_task(actual)
    binding = actual.binding
    workflow = SimpleNamespace(specialist=lambda source: binding, binding_context=lambda source: actual.context, is_job_source=lambda source: False, permits_common_action=lambda source, kind: kind in binding.permitted_common_actions(actual.context), knowledge=SimpleNamespace(instructions='\nOriginal knowledge guidance'), launch_instructions=SimpleNamespace(instructions='\nPinned launch guidance'), native_event_information=object(), decision_protocol='decision_exchange_v1')
    original = own('runtime_prompt').instructions
    workflow.services = SimpleNamespace(instructions=original)
    task.workflow = workflow
    context = {'tool_knowledge': {}, 'launch_instruction_library': {}}
    assert task.instructions(context) == original(task, context)
    text = task.instructions(context)
    assert text.startswith(binding.instructions(actual.context))
    assert 'Original knowledge guidance' in text and 'Pinned launch guidance' in text
    assert ('Waiting only reports readiness and earns no scientific credit.' in text) == ('wait' in binding.permitted_common_actions(actual.context))
    assert (own('runtime_prompt').REASONING_COMMIT_REQUIREMENT in text) == ('reason' in binding.permitted_common_actions(actual.context))

