@pytest.mark.parametrize('actual', ['execution_job_submission', 'structural_homology_evidence/execution_job_submission', 'hpc_work_planning/execution_job_submission', 'hpc_work_planning/hpc_allocation_execution/execution_job_submission', 'structural_homology_evidence/hpc_work_planning/execution_job_submission', 'structural_homology_evidence/hpc_work_planning/hpc_allocation_execution/execution_job_submission'], indirect=['actual'], ids=['home=execution_job_submission', 'home=structural_homology_evidence/execution_job_submission', 'home=hpc_work_planning/execution_job_submission', 'home=hpc_work_planning/hpc_allocation_execution/execution_job_submission', 'home=structural_homology_evidence/hpc_work_planning/execution_job_submission', 'home=structural_homology_evidence/hpc_work_planning/hpc_allocation_execution/execution_job_submission'])
def test_fresh_decision_preserves_context_and_answered_call_replay(actual, monkeypatch):
    v = actual
    task = make_task(v)
    sent = []
    work_report = own('episode_work_report')
    monkeypatch.setattr(work_report, 'completed_action_reports', lambda *args, **kwargs: {'actual_attempts': []})
    response = {'selection': {'kind': 'tool', 'tool': 'execution.capabilities', 'arguments': {}}, 'report_update': {}}

    async def complete(*args, **kwargs):
        sent.append((args, kwargs))
        return deepcopy(response)
    workflow = SimpleNamespace(journal=v.journal, contract_information_profile=lambda source: None, resource_context=lambda source: None, shared_information_context=lambda source: None, launch_instructions=SimpleNamespace(context=lambda: {}, materialize=lambda value: None, instructions=''), available_child_roles=lambda source: (), episode_bindings=SimpleNamespace(initial_decision_context=lambda context: {}), binding_context=lambda source: v.context, specialist=lambda source: v.binding, is_job_source=lambda source: False, execution_expectations=None, resource_estimator=None, native_estimation_context=lambda *args: None, native_event_information=None, permits_common_action=lambda source, kind: kind in v.binding.permitted_common_actions(v.context), waiting_support=lambda *args: {'original_wait': True}, freeze_literature_numerical_contracts=lambda *args: None, decision_protocol=None, receipts=None, provider=SimpleNamespace(has_session=lambda *args: True, complete=complete, complete_with_presentation=complete), services=SimpleNamespace(instructions=own('runtime_prompt').instructions))
    task.workflow = workflow
    schema = v.runtime._object({'selection': {'anyOf': [v.runtime._object({'kind': {'const': 'tool'}, 'tool': {'const': 'execution.capabilities'}, 'arguments': v.runtime._object({})})]}, 'report_update': v.runtime._object({})})
    context = {'execution_assignment': deepcopy(v.assignment), 'current_credit': 2.5, 'visible_record_refs': [], 'pending_work': []}
    result = asyncio.run(task.call(context, schema))
    assert result[0] == response and result[1] == 0 and (result[3] == schema) and (len(sent) == 1)
    assert result[2]['execution_assignment'] == v.assignment and result[2]['current_credit'] == 2.5
    if 'wait' in v.binding.permitted_common_actions(v.context):
        assert result[2]['waiting_support'] == {'original_wait': True}
    else:
        assert 'waiting_support' not in result[2]
    assert result[2]['completed_action_reports'] == {'actual_attempts': []}
    assert sent[0][1] == {}
    task.calls = 0
    workflow.episode_bindings.initial_decision_context = lambda context: pytest.fail('answered replay rebuilt current input')
    replay = asyncio.run(task.call({'changed': True}, {'changed': True}))
    assert replay == result and len(sent) == 1

